/**
 * @file load_inertial.h
 * @brief Declares equivalent loads for prescribed rigid-body acceleration.
 *
 * `InertialLoad` evaluates the acceleration field generated by translation,
 * angular acceleration and angular velocity about a reference point. Structural
 * elements integrate the negative acceleration with distributed density and
 * optional point-mass handling adds concentrated inertia contributions.
 *
 * Inertia loading modifies only the structural right-hand side. The optional
 * system DOF map and LHS triplet list in the common load interface are unused.
 *
 * @see InertialLoad
 * @see Neumann
 * @see load_inertial.cpp
 * @author Finn Eggers
 * @date 30.08.2026
 */

#pragma once

#include "neumann.h"

#include "../../data/region.h"

namespace fem::bc {

/**
 * @brief Represents a translational and rotational rigid-body inertia field.
 *
 * At a material position with offset r from `center_`, the prescribed rigid-body
 * acceleration consists of
 *
 *     a = center_acc + alpha cross r + omega cross (omega cross r).
 *
 * Structural elements integrate the opposing density-scaled acceleration into
 * consistent nodal forces. Optional point masses receive the same kinematic
 * field when `consider_point_masses_` is enabled.
 */
struct InertialLoad : Neumann {
    using Ptr = std::shared_ptr<InertialLoad>;

    // Rigid-body kinematic definition in global coordinates.
    Vec3 center_     = {0, 0, 0};
    Vec3 center_acc_ = {0, 0, 0};
    Vec3 omega_      = {0, 0, 0};
    Vec3 alpha_      = {0, 0, 0};

    // Structural elements contributing distributed inertia.
    SPtr<model::ElementRegion> region_ = nullptr;

    // Include auxiliary point-mass elements when true.
    bool consider_point_masses_ = false;

    InertialLoad() = default;
    ~InertialLoad() override = default;

    // Integrate the rigid-body inertia into the six-component structural RHS.
    // Time, amplitude and the optional LHS assembly objects are unused.
    void apply(model::ModelData&       model_data,
               model::Field&           rhs,
               Precision               time,
               bool                    ignore_amplitude = false,
               const SystemDofIds*      system_dof_ids = nullptr,
               TripletList*             lhs = nullptr) override;

    std::string str() const override;
};

} // namespace fem::bc
